/* Independent notice inputs. Files and drafts stay in this browser. */
(()=>{
'use strict';
const D=globalThis.CampusData,A=globalThis.CampusAttachments,$=id=>document.getElementById(id);
const container=$('notice-entries');if(!container)return;
const first=container.firstElementChild,primary=$('notice'),DRAFT='campus-inbox:compose:v2',LEGACY='campus-inbox:draft:v1';
const MAX_ENTRIES=20;let entries=[fresh()],disabled=false,mode='personal',undo=null,undoTimer;
function fresh(text='',files=[]){return {id:crypto.randomUUID(),text,files:[...files],missingFiles:0};}
function make(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function error(message){window.dispatchEvent(new CustomEvent('campus-composer-error',{detail:{message}}));}
function sync(){container.querySelectorAll('.compose-entry').forEach((row,i)=>{if(entries[i])entries[i].text=row.querySelector('textarea').value;});}
function current(){sync();return entries.map(e=>({id:e.id,text:e.text,files:[...e.files],fileCount:e.files.length+(e.missingFiles||0)}));}
function count(){return current().reduce((n,e)=>n+e.text.length,0);}
function persist(){if(mode!=='personal')return;try{if(entries.some(e=>e.text||e.files.length||e.missingFiles)){localStorage.setItem(DRAFT,JSON.stringify({version:2,entries:entries.map(e=>({id:e.id,text:e.text,fileCount:e.files.length+(e.missingFiles||0)}))}));localStorage.setItem(LEGACY,entries[0].text);}else{localStorage.removeItem(DRAFT);localStorage.removeItem(LEGACY);}}catch{}}
function notify(save=true){sync();const chars=count();$('char-count').textContent=`${chars.toLocaleString('en-US')} / 4,000 字`;$('char-count').classList.toggle('at-limit',chars>=D.MAX_TEXT);document.querySelector('.compose').dataset.entryCount=entries.length;$('notice-add').disabled=disabled||mode==='demo'||entries.length>=MAX_ENTRIES;const missing=entries.some(e=>e.missingFiles>0);$('compose-draft-note').hidden=!missing;if(missing)$('compose-draft-note').textContent='草稿已恢复，附件需重新添加。';if(save)persist();window.dispatchEvent(new CustomEvent('campus-composer-change',{detail:{chars,entries:entries.length,overLimit:chars>D.MAX_TEXT}}));}
function renderFiles(row,entry){const target=row.querySelector('.selected-files');target.replaceChildren();entry.files.forEach((file,index)=>{const chip=make('div','file-chip');chip.append(make('span',null,file.name));const remove=make('button',null,'×');remove.type='button';remove.disabled=disabled||mode==='demo';remove.setAttribute('aria-label',`移除 ${file.name}`);remove.addEventListener('click',()=>{if(disabled||mode==='demo')return;entry.files.splice(index,1);renderFiles(row,entry);notify();});chip.append(remove);target.append(chip);});}
function choose(entry,row,input){if(disabled||mode==='demo')return;try{const next=[...entry.files,...input.files];A.validate(next);const total=entries.reduce((n,e)=>n+(e===entry?next:e.files).reduce((s,f)=>s+f.size,0),0);if(total>A.MAX_TOTAL)throw new Error('本次附件合计不能超过20 MB。');entry.missingFiles=Math.max(0,entry.files.length+(entry.missingFiles||0)-next.length);entry.files=next;renderFiles(row,entry);notify();}catch(e){error(e.message);}finally{input.value='';}}
function clearUndo(){clearTimeout(undoTimer);undo=null;$('compose-undo').hidden=true;}
function removeEntry(index){if(disabled||mode==='demo')return;sync();const removed=entries[index];clearUndo();undo={entry:removed,index};entries.splice(index,1);if(!entries.length)entries=[fresh()];render();notify();$('compose-undo').hidden=false;undoTimer=setTimeout(clearUndo,10000);}
function bindRow(row,entry,index,isPrimary=false){
 row.dataset.entryId=entry.id;const input=row.querySelector('textarea'),label=row.querySelector('label'),remove=row.querySelector('.compose-entry-remove'),attach=row.querySelector('.attachment-button'),upload=row.querySelector('input[type=file]');
 if(!isPrimary){input.id='notice-'+entry.id;label.htmlFor=input.id;input.addEventListener('input',()=>{entry.text=input.value;notify();});remove.addEventListener('click',()=>removeEntry(entries.findIndex(e=>e.id===entry.id)));attach.addEventListener('click',()=>upload.click());upload.addEventListener('change',()=>choose(entry,row,upload));}
 input.value=entry.text;input.readOnly=disabled||mode==='demo';label.textContent=`通知 ${index+1}`;remove.setAttribute('aria-label',`移除通知 ${index+1}`);remove.disabled=disabled||mode==='demo';attach.setAttribute('aria-label',`为通知 ${index+1} 添加附件`);attach.disabled=disabled||mode==='demo';upload.disabled=disabled||mode==='demo';renderFiles(row,entry);
}
function render(newID){
 container.querySelectorAll('.compose-entry').forEach(row=>{if(row!==first)row.remove();});bindRow(first,entries[0],0,true);
 entries.slice(1).forEach((entry,i)=>{const row=make('section','compose-entry'+(entry.id===newID?' is-new':'')),head=make('div','compose-entry-head'),label=make('label','input-label'),remove=make('button','icon-button compose-entry-remove','×');remove.type='button';head.append(label,remove);const input=make('textarea');input.maxLength=D.MAX_TEXT;input.placeholder='粘贴这一条通知的原文……';input.setAttribute('aria-describedby','char-count');const fileRow=make('div','compose-entry-files'),attach=make('button','attachment-button icon-button','＋');attach.type='button';attach.title='添加附件';fileRow.append(attach,make('div','selected-files'));const upload=make('input');upload.type='file';upload.multiple=true;upload.hidden=true;row.append(head,input,fileRow,upload);container.append(row);bindRow(row,entry,i+1);});notify(false);
}
primary.addEventListener('input',()=>{entries[0].text=primary.value;notify();});first.querySelector('.compose-entry-remove').addEventListener('click',()=>removeEntry(0));$('attach').addEventListener('click',()=>{if(!disabled&&mode!=='demo')$('attachment-file').click();});$('attachment-file').addEventListener('change',()=>choose(entries[0],first,$('attachment-file')));
$('notice-add').addEventListener('click',()=>{if(disabled||mode==='demo'||entries.length>=MAX_ENTRIES)return;sync();const entry=fresh();entries.push(entry);render(entry.id);notify();const row=container.lastElementChild;row.querySelector('textarea').focus({preventScroll:true});row.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
$('compose-undo-button').addEventListener('click',()=>{if(!undo||disabled||mode==='demo')return;sync();const old=undo;if(entries.length===1&&!entries[0].text&&!entries[0].files.length)entries=[];if(entries.length>=MAX_ENTRIES){error('已达到20条，请先移除一条再撤销。');return;}entries.splice(Math.min(old.index,entries.length),0,old.entry);clearUndo();render();notify();});
function restore(snapshot,{persist:save=false}={}){if(!Array.isArray(snapshot)||!snapshot.length||snapshot.length>MAX_ENTRIES)throw new Error('通知草稿格式不正确。');const ids=new Set();entries=snapshot.map(e=>{if(!e||typeof e.text!=='string'||e.text.length>D.MAX_TEXT)throw new Error('通知草稿格式不正确。');const id=typeof e.id==='string'&&e.id.length<=80&&!ids.has(e.id)?e.id:crypto.randomUUID();ids.add(id);const files=Array.isArray(e.files)?[...e.files]:[];A.validate(files);const fileCount=Number.isInteger(e.fileCount)&&e.fileCount>=0&&e.fileCount<=10?e.fileCount:files.length;return {id,text:e.text,files,missingFiles:Math.max(0,fileCount-files.length)};});clearUndo();render();notify(save);}
function prepare(){const all=current();all.forEach((e,i)=>{if(!e.text.trim()&&e.files.length)throw new Error(`请补充通知 ${i+1} 的正文。`);A.validate(e.files);});if(count()>D.MAX_TEXT)throw new Error('本次通知合计不能超过4,000字，请删减或分批整理。');const selected=all.filter(e=>e.text.trim()),texts=selected.map(e=>e.text.trim()),files=[],owners=[];selected.forEach((e,i)=>e.files.forEach(f=>{files.push(f);owners.push(i);}));if(files.reduce((n,f)=>n+f.size,0)>A.MAX_TOTAL)throw new Error('本次附件合计不能超过20 MB。');return {request:{sources:texts.map(text=>({text}))},originals:texts,files,owners,explicit:true};}
try{const raw=localStorage.getItem(DRAFT);if(raw&&raw.length<120000){const draft=JSON.parse(raw);if(draft.version===2&&Array.isArray(draft.entries)&&draft.entries.length&&draft.entries.length<=MAX_ENTRIES){restore(draft.entries);if(draft.entries.some(e=>e.fileCount>0)){$('compose-draft-note').textContent='草稿已恢复，附件需重新添加。';$('compose-draft-note').hidden=false;}}}else{const old=localStorage.getItem(LEGACY);if(old&&old.length<=D.MAX_TEXT)entries[0].text=old;}}catch{}
render();
globalThis.CampusComposer={getEntries:current,snapshot:current,prepare,getRequest:()=>prepare().request,getInput:()=>prepare().originals.join('\n\n---\n\n'),restore,
 clear({persist:save=true}={}){entries=[fresh()];clearUndo();$('compose-draft-note').hidden=true;render();notify(save);},
 setDisabled(value){sync();disabled=!!value;render();notify(false);},
 setMode(value){sync();mode=value==='demo'?'demo':'personal';render();notify(false);},
 renderFiles(){container.querySelectorAll('.compose-entry').forEach((row,i)=>renderFiles(row,entries[i]));},
 setText(text){restore([fresh(text)]);notify();},
 key:DRAFT,maxEntries:MAX_ENTRIES};
})();
